/**
 * lote24.php — Los dos remates de tu lista de siete. Y el lote 21 dentro.
 *
 * REQUIERE el lote 23 aplicado.
 *
 * INCLUYE EL LOTE 21, que llevaba tres entregas sin aplicarse en tu carpeta. En
 * vez de volver a pedírtelo lo he metido aquí: sin él, todo el trabajo de los
 * lotes 18 a 20 está en la base de datos pero el despachador no lo ve al
 * asignar conductor. Cuando esto pase, borra `lote21.php` de la raíz — ya no
 * hace falta. (Si lo ejecutas igualmente, dirá «ya estaba»: es idempotente.)
 *
 * Qué instala, además del 21:
 *
 *   • BUSCADOR DE TRANSPORTISTA al dar de alta un conductor. Era una lista de
 *     casillas: deja de servir alrededor de los treinta transportistas y es
 *     hostil a los doscientos. Ahora se escriben tres letras y se elige de uno
 *     en uno. Se pueden seguir poniendo varios —el esquema lo admite y hay
 *     conductores que trabajan para dos— y el primero sigue siendo el
 *     principal, como antes.
 *
 *   • TIPOS DE DOCUMENTO YA SUBIDOS, APAGADOS. Al elegir el dueño, el
 *     formulario pregunta al servidor qué tipos tiene ya y apaga esas opciones,
 *     con enlace al documento que las ocupa. Subir «certificado de seguro» dos
 *     veces no crea dos documentos: crea uno bueno y otro que nadie sabe si
 *     mirar. Lo que se quiere ahí es una VERSIÓN NUEVA del que está, y eso se
 *     hace desde su ficha.
 *
 *     Se pide por recarga parcial al elegir dueño, no mandando el mapa entero:
 *     una empresa con doscientos transportistas enviaría kilos de JSON para
 *     usar una fila. Y el ámbito se comprueba igual que en el resto — pedir por
 *     la URL el dueño de otra empresa no devuelve nada.
 *
 *   • 5 pruebas nuevas, incluida la del intento por URL cruzando empresas.
 *
 * Sin migración.
 *
 * Cómo se ejecuta, desde la raíz del repositorio:
 *
 *     php lote24.php            # aplica
 *     php lote24.php --dry-run  # dice qué haría y no toca nada
 */

$raiz = __DIR__;
$dry = in_array('--dry-run', $argv, true);
$hechos = []; $saltados = []; $errores = [];

function ruta(string $rel): string { global $raiz; return $raiz.DIRECTORY_SEPARATOR.$rel; }

function nuevo(string $rel, string $contenido): void
{
    global $dry, $hechos, $saltados, $errores;
    $destino = ruta($rel);
    if (is_file($destino) && file_get_contents($destino) === $contenido) { $saltados[] = "= {$rel}"; return; }
    $existia = is_file($destino);
    if ($dry) { $hechos[] = ($existia ? '~ ' : '+ ').$rel; return; }
    $dir = dirname($destino);
    if (! is_dir($dir) && ! mkdir($dir, 0775, true) && ! is_dir($dir)) { $errores[] = "no se pudo crear el directorio {$dir}"; return; }
    if (file_put_contents($destino, $contenido) === false) { $errores[] = "no se pudo escribir {$rel}"; return; }
    $hechos[] = ($existia ? '~ ' : '+ ').$rel;
}

/**
 * Aplica trozos anclados. Si el resultado ya está, se salta; si el texto de
 * partida está una sola vez, se sustituye; si no, se aborta el fichero entero
 * sin escribir — un anclaje que no encaja significa que el fichero no es el que
 * este guion vio, y adivinar ahí es peor que parar.
 *
 * @param  list<array{0: string, 1: string}>  $pares
 */
function editar(string $rel, array $pares): void
{
    global $dry, $hechos, $saltados, $errores;
    $destino = ruta($rel);
    if (! is_file($destino)) { $errores[] = "falta {$rel} — ¿está en la raíz del repositorio?"; return; }
    $texto = file_get_contents($destino); $aplicados = 0; $yaEstaban = 0;
    foreach ($pares as $i => [$antes, $despues]) {
        if (str_contains($texto, $despues)) { $yaEstaban++; continue; }
        $veces = substr_count($texto, $antes);
        if ($veces !== 1) { $errores[] = "{$rel}: el trozo #".($i + 1)." no encaja ({$veces} coincidencias). No se tocó el fichero."; return; }
        $texto = str_replace($antes, $despues, $texto); $aplicados++;
    }
    if ($aplicados === 0) { $saltados[] = "= {$rel} ({$yaEstaban} trozo(s) ya estaban)"; return; }
    if ($dry) { $hechos[] = "~ {$rel} ({$aplicados} trozo(s))"; return; }
    if (file_put_contents($destino, $texto) === false) { $errores[] = "no se pudo escribir {$rel}"; return; }
    $hechos[] = "~ {$rel} ({$aplicados} trozo(s))";
}

foreach (['artisan', 'composer.json', 'app/Support/Navigation.php'] as $centinela) {
    if (! is_file(ruta($centinela))) {
        fwrite(STDERR, "Esto no parece la raíz del repositorio: falta {$centinela}.\n");
        exit(1);
    }
}

